// src/components/Dashboard/ReleaseView/ReleaseQEHome.js
import React from 'react';

/**
 * [PH1-C] Release QE Home
 * Phase 1: placeholder surface. Phase 2 will read the Excel (TQI CBPT Releases DSR as of Oct 08.xlsm)
 * sheet "Daily Dashboard" and provide edit + save (likely via SheetJS + backend API).
 */
export default function ReleaseQEHome({ release }) {
  return (
    <div>
      <div className="muted" style={{ marginBottom: 8 }}>
        Release QE Home for <b>{release || '—'}</b>
      </div>
      <div className="muted">
        Excel “Daily Dashboard” view will be wired in Phase 2 (edit & save with backend persistence).
      </div>
    </div>
  );
}
